(501430, 49155, 10510, '<td valign="top">10, even though I would like for the highlights to cover more of the top of the hair and the brush.  This is a very beautiful photo.</td>', '10, even though I would like for the highlights to cover more of the top of the hair and the brush.  This is a very beautiful photo.', '2003-12-02 19:08:28.000000', NULL, 1),
(501431, 49103, 7369, '<td valign="top">Because of the excellent use of colours, the composition and the soft focus I will give you a ten!</td>', 'Because of the excellent use of colours, the composition and the soft focus I will give you a ten!', '2003-12-02 19:09:35.000000', NULL, 1),
