(505516, 48885, 11895, '<td valign="top">love the colors and the border</td>', 'love the colors and the border', '2003-12-06 16:16:56.000000', NULL, 1),
(505530, 49106, 13749, '<td valign="top">lovely image and use of soft focus.  the reflections are beautiful and i like how buoys in the back seem slightly more covered by the fog (?).  the triangle formed is interesting.  i want to say a tighter crop might have been nice.. but on the other hand, the feeling of emptiness is good for this photo.. nice work.</td>', 'lovely image and use of soft focus.  the reflections are beautiful and i like how buoys in the back seem slightly more covered by the fog (?).  the triangle formed is interesting.  i want to say a tighter crop might have been nice.. but on the other hand, the feeling of emptiness is good for this photo.. nice work.', '2003-12-06 17:08:18.000000', NULL, 1),
(505531, 49105, 11895, '<td valign="top">good idea and well executed</td>', 'good idea and well executed', '2003-12-06 17:10:12.000000', NULL, 1),
(505534, 49143, 11895, '<td valign="top">very cute little girl but the pink is not her color</td>', 'very cute little girl but the pink is not her color', '2003-12-06 17:17:37.000000', NULL, 1),
(505580, 48945, 3032, '<td valign="top">Excellent filling of the frame and the lighting causes it to be right in your face. Good tonal balance, no blowout yet strong contrast between fore- and background. Good color, well chosen subject for a soft focus.</td>', 'Excellent filling of the frame and the lighting causes it to be right in your face. Good tonal balance, no blowout yet strong contrast between fore- and background. Good color, well chosen subject for a soft focus.', '2003-12-06 18:39:47.000000', NULL, 1),
(505584, 49106, 3032, '<td valign="top">Like the tranquility of this photo. Seems like a early misty morning to me.<br/>Perhaps some tighter cropping would work better, but I like the mood of this. It is like redmapper''s "Dream of the Past" (Unfortunately disqualified because of  a wrong date).<br/>Nice work!</td>', 'Like the tranquility of this photo. Seems like a early misty morning to me.Perhaps some tighter cropping would work better, but I like the mood of this. It is like redmapper''s "Dream of the Past" (Unfortunately disqualified because of  a wrong date).Nice work!', '2003-12-06 18:42:33.000000', NULL, 1),
(505585, 48705, 3032, '<td valign="top">This girl has a lovely face and great eyes, well portrayed.</td>', 'This girl has a lovely face and great eyes, well portrayed.', '2003-12-06 18:44:05.000000', NULL, 1),
(505596, 49154, 13403, '<td valign="top">the branches are too crowded in the picture..  if you could''ve gotten a better angle.. plus its just me, but i don''t like soft focus wildlife shots;)</td>', 'the branches are too crowded in the picture..  if you could''ve gotten a better angle.. plus its just me, but i don''t like soft focus wildlife shots;)', '2003-12-06 19:04:34.000000', NULL, 1),
